import { describe, it, expect, beforeEach, vi } from 'vitest';
import { createPost, getPosts } from '../src/services/postService';

describe('PostService', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  it('should create a blog post with valid inputs', async () => {
    const post = await createPost({ title: 'Test Title', content: 'Test Content', author: 'Author' });
    expect(post).toHaveProperty('id');
    expect(post.title).toBe('Test Title');
  });

  it('should throw an error when title is missing', async () => {
    await expect(createPost({ title: '', content: 'Test Content', author: 'Author' })).rejects.toThrow('Title is required');
  });
});

export interface PostInput {
  title: string;
  content: string;
  author: string;
}

export interface Post extends PostInput {
  id: string;
  createdAt: Date;
}

const posts: Post[] = [];

export async function createPost(input: PostInput): Promise<Post> {
  if (!input.title || input.title.trim() === '') {
    throw new Error('Title is required');
  }
  const newPost: Post = {
    id: Math.random().toString(36).substring(2, 9),
    ...input,
    createdAt: new Date()
  };
  posts.push(newPost);
  return newPost;
}

export async function getPosts(): Promise<Post[]> {
  return posts;
}

